import{_ as r,h as n,i as e,c as i,v as t,p as s,x as o,m,e as h,S as p}from"./chunks/framework.Dvtg8yj2.js";const P=JSON.parse('{"title":"Llama 3.1 长上下文","description":"","frontmatter":{"title":"Llama 3.1 长上下文","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llama-3-1.md","filePath":"llm/llama-3-1.md","lastUpdated":1788454257000}'),d={name:"llm/llama-3-1.md"};function E(B,a,c,A,K,_){const l=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="llama-3-1-长上下文" tabindex="-1">Llama 3.1 长上下文 <a class="header-anchor" href="#llama-3-1-长上下文" aria-label="Permalink to &quot;Llama 3.1 长上下文&quot;">​</a></h1><div class="epigraph"><p>标准预训练在 8K 窗口上完成，随后用持续预训练把支持的上下文逐步拉到 128K。</p><footer>—— Grattafiori 等，The Llama 3 Herd of Models，arXiv:2407.21783</footer></div><p>Llama 3.1 把「能读多长」写成产品规格：公开权重覆盖 8B、70B 与 405B，窗口标称 <strong>128K token</strong>。论文把评测表里的结果都算在 Llama 3.1 上，并声明为行文方便仍称 Llama 3。长窗口不是把 <code>max_position_embeddings</code> 改成 131072 再直接推理——那会把 <a href="/llm/rope">RoPE</a> 的相位送出训练支撑。真正改的是两件事：预训练后期用更长序列做持续训练；位置通道用高基数与按维缩放，把外推与插值拆开处理。本篇只谈这条 8K→128K 的工程，不把 405B 的数据配比或后训练工具调用写成另一篇综述。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Llama 3 主体预训练在 <strong>8K</strong> 上做 next-token prediction（405B 约 15.6T token）。自注意力按长度二次涨，一开始就按 128K 训，同样 token 预算下步数会少一个数量级。短窗模型若在推理时把位置下标直接用到 \\(L&#39;=128\\mathrm{K}\\)，高频旋转角走出训练弧长，点积不再编码相对距离，这是 <a href="/llm/position-extrapolation">朴素外推</a> 的典型失败。</p><p>另一方面，把所有频率按 \\(8\\mathrm{K}/128\\mathrm{K}\\) 线性压缩（位置插值）能把相位映回原窗口，但高频邻域被抹平，近距离复制与局部语法会伤。需要的是一条<strong>可验收的拉长课程</strong>：每加一档长度，短任务分数要回到原水平，长任务上「大海捞针」一类检索要过关，而不是只看能不能把 KV 塞进显存。</p><h3 id="_128k-是训练出来的窗口-不是配置项" tabindex="-1">128K 是训练出来的窗口，不是配置项 <a class="header-anchor" href="#_128k-是训练出来的窗口-不是配置项" aria-label="Permalink to &quot;128K 是训练出来的窗口，不是配置项&quot;">​</a></h3><p>标称上下文是模型在该长度上被训过、并且用检索与长文档基准验收过的上限。推理框架把缓存开到 128K，只说明数值与掩码允许前向。没有分阶段适应时，困惑度会在某一长度陡升；有适应但后训练全是短对话时，模型会把后半段当噪声。Llama 3.1 把长序列放到预训练<strong>最后阶段</strong>，再在后训练里单独配长上下文 SFT，就是在避免这两种假窗口。</p><p><span class="marginnote">论文写明：过早用长序列不划算，因为注意力计算随长度二次增长。长上下文是课程的最后几课，不是第零课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="高基数-rope-先把外推余量留出来" tabindex="-1">高基数 RoPE 先把外推余量留出来 <a class="header-anchor" href="#高基数-rope-先把外推余量留出来" aria-label="Permalink to &quot;高基数 RoPE 先把外推余量留出来&quot;">​</a></h3><p>Llama 3 把 RoPE 基数从 Llama 2 常用的 \\(10^4\\) 提到 \\(\\theta=500{,}000\\)。Xiong 等人（2023）表明，提高基数有利于把窗口做到数万 token 量级。高 \\(\\theta\\) 让同一下标对应的高频转得更慢，8K 预训练里相位尚未把后续拉长用尽。这是<strong>外推友好的尺子</strong>，本身还不等于 128K 已经可用。</p><h3 id="分阶段持续预训练" tabindex="-1">分阶段持续预训练 <a class="header-anchor" href="#分阶段持续预训练" aria-label="Permalink to &quot;分阶段持续预训练&quot;">​</a></h3><p>405B 的长上下文阶段大约用 <strong>800B token</strong>，从 8K 起分 <strong>六档</strong> 加长，直到 128K。每一档的验收有两条：(1) 短上下文评测完全恢复；(2) 直到该长度的 needle-in-a-haystack 能完美取回。不满足就继续在该档上训，而不是一次跳到 16 倍。退火阶段仍保持 128K，并上采样高质量数据。上下文并行（context parallelism）按序列维切块，使 128K 训练在显存上可行。</p><p>后训练里，SFT 要显式混入 16K、32K、64K、128K 档的样本，以免对齐把长程注意力洗掉。论文观察到：只要 SFT 的长上下文已经够好，DPO 只用短样本也不至于把长能力打崩——DPO 步数更少。这是配方观察，不是「DPO 天然保护长窗口」的定理。</p>',15)),(e(),s(p,null,{default:o(()=>[h(l,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20P8%5B%228K%20%E4%B8%BB%E4%BD%93%E9%A2%84%E8%AE%AD%E7%BB%83%20%CE%B8%3D500k%22%5D%20--%3E%20S%5B%22%E5%88%86%E9%98%B6%E6%AE%B5%E5%8A%A0%E9%95%BF%E5%BA%8F%E5%88%97%22%5D%0A%20%20S%20--%3E%20A1%5B%22%E7%9F%AD%E4%BB%BB%E5%8A%A1%E5%88%86%E6%95%B0%E6%81%A2%E5%A4%8D%22%5D%0A%20%20S%20--%3E%20A2%5B%22%E8%AF%A5%E9%95%BF%E5%BA%A6%E9%92%88%E6%A3%80%E7%B4%A2%E9%80%9A%E8%BF%87%22%5D%0A%20%20A1%20--%3E%20P128%5B%22128K%20%E9%80%80%E7%81%AB%E4%B8%8E%E6%A3%80%E6%9F%A5%E7%82%B9%E5%B9%B3%E5%9D%87%22%5D%0A%20%20A2%20--%3E%20P128%0A%20%20P128%20--%3E%20SFT%5B%22%E9%95%BF%E7%9F%AD%E6%B7%B7%E6%B4%97%E7%9A%84%20SFT%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22%E7%9F%AD%E6%A0%B7%E6%9C%AC%E4%B8%BA%E4%B8%BB%E7%9A%84%20DPO%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="推理期的按维频率缩放" tabindex="-1">推理期的按维频率缩放 <a class="header-anchor" href="#推理期的按维频率缩放" aria-label="Permalink to &quot;推理期的按维频率缩放&quot;">​</a></h3><p>发布权重在推理实现里并不对所有旋转维做同一缩放。官方配套方案（transformers 中 <code>rope_type=llama3</code>）按波长分段：波长短于原窗口某一阈值的维<strong>保持原频率</strong>（保局部、接近外推）；波长长的维把频率除以缩放系数（低频插值）；中间段斜坡混合。这与 <a href="/llm/ntk-aware-interpolation">NTK-aware</a> / <a href="/llm/yarn">YaRN</a> 的「高频少压、低频多担外推」同族，但是 Llama 3.1 自己的一套系数，写进配置而不是另训一份位置网络。训练课程与推理缩放必须配对：用 8K 的 RoPE 核去跑 128K 的 3.1 权重，相位会错。</p><p><span class="marginnote">不要把 \\(\\theta=500{,}000\\) 写成「已经等于 128K」。高基数是 8K 预训练时的外推余量；128K 来自分阶段持续预训练。推理缩放是第三块拼图，缺一角就会在某一频段上重复插值或重复外推的失败模式。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>记原窗口 \\(L=8192\\)，目标 \\(L&#39;=131072\\)。朴素外推使用真实下标 \\(p\\) 与原 \\(\\theta_i\\)，失败在高频。全局插值使用 \\(p\\cdot L/L&#39;\\)，失败在高频被压缩。Llama 3.1 的组合是：先用很大的基数降低「同一 \\(p\\) 上转得有多快」，再用持续训练让注意力权重看见过 \\(L&#39;\\) 量级的键集合，最后在推理把低频维按比例放慢、高频维尽量不动。低频负责「文档前部还是后部」，高频负责「差几个 token」。分段以后，softmax 才同时保得住远距检索与近距语法。</p><p>针检索完美，只说明存在一条高分路径能把插入句取回。多针、长文档 QA、需要综合多段的任务，才测「窗口里的内容有没有被用上」。论文在 InfiniteBench、ZeroSCROLLS 等长上下文基准上另外报表，并讨论 DocQA 与 many-shot 上的安全：上下文变长后，有害示范与文档内对抗问题会进入同一窗口，安全后训练必须覆盖长前缀，不能只做短对话拒绝。</p><h3 id="与「开源侧插值补丁」的差别" tabindex="-1">与「开源侧插值补丁」的差别 <a class="header-anchor" href="#与「开源侧插值补丁」的差别" aria-label="Permalink to &quot;与「开源侧插值补丁」的差别&quot;">​</a></h3><p>2023 年社区把 Llama 2 拉到 16K/32K，多用位置插值或改基数再少量微调。Llama 3.1 把同类几何放进<strong>官方预训练课程</strong>，用的 token 量是「微调几千步」的许多倍，并且用短任务回归当门禁。效果上 128K 是一等公民；代价是训练集群必须支持上下文并行与长序列通信。不能把 3.1 的 128K 理解成「在 3.0 8K 权重上套一层 YaRN」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>128K 的 KV 按层、按 <a href="/llm/gqa">GQA</a> 头数线性涨。405B 即使用分组 KV，服务 128K 仍是带宽与显存问题，多数业务到不了标称上限。针检索过关不等于代码仓库级推理过关：仓库补全还依赖数据里是否出现过跨文件模式。后训练若把长样本洗掉，窗口规格还在卡上，行为回到短对话模型。</p><p>分阶段门禁依赖针任务，会偏向「能定位一句」而不是「能维护万 token 的约束」。评自己的 3.1 部署时，应同时看短任务回归、针检索、以及需要综合的长文档，三张表缺一不可。</p><p><span class="marginnote">Llama 3.1 的多模态实验在论文里是组合式适配器，不是原生早融合；长上下文规格首先是语言模型窗口。不要把 128K 自动写成「128K 图像 token」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Llama 3.1 把上下文从 8K 拉到 128K：主体仍在短窗预训练，长序列放在持续预训练与后训练。</li><li>RoPE 使用 \\(\\theta=500{,}000\\)，为后续拉长留外推余量；真正的 128K 靠分阶段加长与约 800B token（405B）的长上下文阶段。</li><li>推理配套按波长分段缩放频率：低频插值、高频少动，避免单一的外推崩溃或插值糊掉。</li><li>验收要短任务恢复加针检索；安全评测必须覆盖长文档与 many-shot。</li><li>出处：Grattafiori 等，<em>The Llama 3 Herd of Models</em>，arXiv:2407.21783（文中评测对应 Llama 3.1）。RoPE 缩放实现见官方权重配置与推理代码；对照 Chen 等位置插值（2023）、Peng 等 YaRN（2023）、Xiong 等长上下文 RoPE（2023）。</li></ul>',14))])}const u=r(d,[["render",E]]);export{P as __pageData,u as default};
